<?php


namespace SwitcherCore\Switcher\Console;

use Exception;
use Meklis\Network\Console\Helpers\HelperInterface;
use Meklis\Network\Console\SSH;

class SshLazyConnect extends SSH implements ConsoleInterface
{
    protected $host;
    protected $port;
    protected $username;
    protected $password;
    protected $isLogined = false;

    /** Re-entrancy guard — see TelnetLazyConnect::$isConnecting. login()'s
     *  own after-login commands re-enter exec() before isLogined is set,
     *  which without this recurses into connect+login without bound. */
    protected $isConnecting = false;

    public function exec($command, $add_newline = true, $prompt = null)
    {
        if (!$this->isLogined && !$this->isConnecting) {
            // PATCHED: flag set only AFTER both calls succeed. It used to be
            // set first, so any failure left this object permanently
            // believing it was logged in while never having connected —
            // every later exec() then skipped reconnecting and wrote onto a
            // dead socket. Same bug (and same fix) as TelnetLazyConnect.
            $this->isConnecting = true;
            try {
                $this->connect($this->host, $this->port);
                $this->login($this->username, $this->password);
                $this->isLogined = true;
            } finally {
                $this->isConnecting = false;
            }
        }
        return parent::exec($command, $add_newline, $prompt); // TODO: Change the autogenerated stub
    }

    /**
     * PATCHED: see TelnetLazyConnect::disconnect() — the flag has to be
     * cleared with the session, or the cached instance is poisoned rather
     * than freed by the per-request console cleanup in app/server.php.
     */
    public function disconnect()
    {
        $this->isLogined = false;
        return parent::disconnect();
    }

    function connectAndLogin()
    {
        if (!$this->isLogined && !$this->isConnecting) {
            $this->isConnecting = true;
            try {
                $this->connect($this->host, $this->port);
                $this->login($this->username, $this->password);
                $this->isLogined = true;
            } finally {
                $this->isConnecting = false;
            }
        }
        return $this;
    }

    function connectOnly()
    {
        if (!$this->isLogined) {
            $this->connect($this->host, $this->port);
        }
        return $this;
    }

    function setAccess($username, $password)
    {
        $this->username = $username;
        $this->password = $password;
        return $this;
    }

    function setHost($host, $port = 23)
    {
        $this->host = $host;
        $this->port = $port;
        return $this;
    }

    /**
     * @return \Meklis\Network\Console\Helpers\DefaultHelper|HelperInterface
     */
    function getDeviceHelper()
    {
        return $this->helper;
    }

    function setTimeout($timeout)
    {
        $this->timeout = $timeout;
        return $this;
    }

    function setStreamTimeout($timeout)
    {
        $this->stream_timeout_sec = $timeout;
        return $this;
    }

    function getTimeout()
    {
        return $this->timeout;
    }

    function getStreamTimeout()
    {
        return $this->stream_timeout_sec;
    }

    function getStream()
    {
        return $this->session;
    }
}
